510	            throw new AddressException(
511	                    AddressErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
512	                    "배송 상태 조회 중 오류 발생: " + e.getMessage(),
513	                    e
514	            );
515	        }
516	    }
