525	public enum AddressStatus {
526	    PENDING {
527	        @Override
528	        public boolean canTransitionTo(AddressStatus nextStatus) {
529	            return nextStatus == SHIPPED || nextStatus == CANCELED;
530	        }
531	    },
532	    SHIPPED {
533	        @Override
534	        public boolean canTransitionTo(AddressStatus nextStatus) {
535	            return nextStatus == IN_TRANSIT || nextStatus == RETURNED || nextStatus == CANCELED;
536	        }
537	    },
538	    IN_TRANSIT {
539	        @Override
540	        public boolean canTransitionTo(AddressStatus nextStatus) {
541	            return nextStatus == OUT_FOR_DELIVERY || nextStatus == DELAYED || nextStatus == CANCELED
542	                    || nextStatus == DELIVERED;
543	        }
544	    },
545	    OUT_FOR_DELIVERY {
546	        @Override
547	        public boolean canTransitionTo(AddressStatus nextStatus) {
548	            return nextStatus == DELIVERED || nextStatus == FAILED_DELIVERY || nextStatus == CANCELED;
549	        }
550	    },
551	    DELIVERED {
552	        @Override
553	        public boolean canTransitionTo(AddressStatus nextStatus) {
554	            return false;
555	        }
556	    },
557	    RETURNED {
558	        @Override
559	        public boolean canTransitionTo(AddressStatus nextStatus) {
560	            return nextStatus == CANCELED;
561	        }
562	    },
563	    CANCELED {
564	        @Override
565	        public boolean canTransitionTo(AddressStatus nextStatus) {
566	            return false;
567	        }
568	    },
569	    DELAYED {
570	        @Override
571	        public boolean canTransitionTo(AddressStatus nextStatus) {
572	            return nextStatus == IN_TRANSIT || nextStatus == CANCELED;
573	        }
574	    },
575	    FAILED_DELIVERY {
576	        @Override
577	        public boolean canTransitionTo(AddressStatus nextStatus) {
578	            return nextStatus == RETURNED || nextStatus == OUT_FOR_DELIVERY || nextStatus == CANCELED;
579	        }
580	    };
581	
582	    public abstract boolean canTransitionTo(AddressStatus nextStatus);
583	}
