516	    private AddressStatus mapToShipmentStatus(String statusText) {
517	        return switch (statusText) {
518	            case "배송완료" -> AddressStatus.DELIVERED;
519	            case "배송출발" -> AddressStatus.OUT_FOR_DELIVERY;
520	            default -> AddressStatus.IN_TRANSIT;
521	        };
522	    }
